-- Local-only: seven past match cycles (2026-03 to 2026-09) and their matches, giving the
-- matching algorithm a history to avoid repeat pairings against. No pair repeats across
-- cycles. Fixed ids keep this idempotent and clear of cycles created through the UI.
-- Members 1-50 are in every cycle, 51-65 joined in 2026-08 and 66-80 in 2026-09; inactive
-- members only appear in the cycles before they paused. With an odd head count one member
-- sits out each cycle. Pairs are mostly sensible (as if hand-matched) with a few off ones,
-- and match_score uses the current scorers: +20 / -20 compatible / conflicting match pref
-- (0 with No Preference) and +10 same industry.
-- Depends on members from R__Mock_V0001 and R__Mock_V0003.
OVERRIDING SYSTEM VALUE
VALUES
    (8998, '2026-03', '2026-03-01T14:00:00Z', FALSE),
    (8999, '2026-04', '2026-04-01T14:00:00Z', FALSE),
    (9000, '2026-05', '2026-05-01T14:00:00Z', FALSE),
    (9001, '2026-06', '2026-06-01T14:00:00Z', FALSE),
    (9002, '2026-07', '2026-07-01T14:00:00Z', FALSE),
    (9003, '2026-08', '2026-08-01T14:00:00Z', FALSE),
    (9004, '2026-09', '2026-09-01T14:00:00Z', FALSE)
ON CONFLICT (id) DO NOTHING;

-- Clear previously seeded mock matches so pairs removed from this file do not linger.
DELETE FROM matches WHERE cycle_id BETWEEN 8998 AND 9004;

